#include "app/AvionicsLab.hpp"
#include "app/ConsoleCockpit.hpp"
#include "config/RunProfile.hpp"
#include "diagnostics/DiagnosticCasebook.hpp"
#include "diagnostics/DiagnosticEngine.hpp"
#include "diagnostics/DiagnosticReport.hpp"
#include "io/SessionArchive.hpp"
#include "release/BuildIdentity.hpp"
#include "report/LabReport.hpp"
#include "sim/ScenarioEngine.hpp"
#include <CLI/CLI.hpp>
#include <chrono>
#include <exception>
#include <iostream>
#include <string>
#include <vector>
using namespace nexvary::avionics;
int main(int argc,char** argv){
 CLI::App app{"NEXVARY Avionics Lab — training/simulation only"};
 const std::string versionText=std::string(build::BuildIdentity::product)+" "+std::string(build::BuildIdentity::version)+" Stage "+std::to_string(build::BuildIdentity::stage);
 app.set_version_flag("--version",versionText);
 std::string scenarioName{"nominal"},profilePath,exportPath,inspectPath,reportJson,reportMd,diagnosticJson,diagnosticMd,diagnosticCasebook;int ticks=40,stepMs=100,trendWindow=0;bool replay=false,list=false,diagnosticSummary=false;
 auto* scenarioOpt=app.add_option("--scenario",scenarioName,"Synthetic scenario");auto* ticksOpt=app.add_option("--ticks",ticks,"Simulation ticks")->check(CLI::Range(1,100000));auto* stepOpt=app.add_option("--step-ms",stepMs,"Simulation step milliseconds")->check(CLI::Range(10,10000));
 app.add_option("--trend-window",trendWindow,"Report statistics over the latest N frames; 0 means all")->check(CLI::Range(0,100000));app.add_option("--profile",profilePath,"JSON training run profile");app.add_flag("--replay",replay,"Replay summaries");app.add_flag("--list-scenarios",list,"List scenarios");app.add_option("--export-json",exportPath,"Export JSON training session");app.add_option("--inspect-json",inspectPath,"Inspect JSON training session");app.add_option("--report-json",reportJson,"Write verification/trend report as JSON");app.add_option("--report-md",reportMd,"Write verification/trend report as Markdown");app.add_option("--diagnostic-json",diagnosticJson,"Write synthetic diagnostic report as JSON");app.add_option("--diagnostic-md",diagnosticMd,"Write synthetic diagnostic report as Markdown");app.add_option("--diagnostic-casebook",diagnosticCasebook,"Write a one-case diagnostic casebook JSON");app.add_flag("--diagnostic-summary",diagnosticSummary,"Print synthetic diagnostic summary");CLI11_PARSE(app,argc,argv);
 try{if(!profilePath.empty()){const auto profile=RunProfile::readFile(profilePath);if(scenarioOpt->count()==0)scenarioName=profile.scenario;if(ticksOpt->count()==0)ticks=profile.ticks;if(stepOpt->count()==0)stepMs=profile.stepMs;if(exportPath.empty())exportPath=profile.exportSession;if(reportJson.empty())reportJson=profile.reportJson;if(reportMd.empty())reportMd=profile.reportMarkdown;}if(list){for(const auto& name:ScenarioEngine::names())std::cout<<name<<'\n';return 0;}if(!inspectPath.empty()){const auto data=SessionArchive::readFile(inspectPath);std::cout<<"SESSION schema="<<data.schema<<" scenario="<<data.scenario<<" frames="<<data.frames.size()<<" events="<<data.events.size()<<'\n';return 0;}AvionicsLab lab(ScenarioEngine::fromName(scenarioName));LabSnapshot last;for(int i=0;i<ticks;++i)last=lab.step(std::chrono::milliseconds{stepMs});ConsoleCockpit::render(std::cout,last);std::cout<<" RECORDED FRAMES: "<<lab.recorder().size()<<" | EVENT COUNT: "<<lab.eventLog().size()<<'\n';if(replay){ReplayCursor cursor(lab.recorder());std::size_t count=0;while(auto frame=cursor.next()){if(count%10==0||!cursor.hasNext())std::cout<<" REPLAY seq="<<frame->sequence<<" time_ms="<<frame->simTime.count()<<" sensors="<<frame->sensors.size()<<'\n';++count;}}if(!exportPath.empty())SessionArchive::writeFile(exportPath,scenarioName,lab.recorder(),lab.eventLog());const auto report=LabReport::analyze(scenarioName,lab.recorder(),lab.eventLog(),static_cast<std::size_t>(trendWindow));if(!reportJson.empty())LabReport::writeJson(reportJson,report);if(!reportMd.empty())LabReport::writeMarkdown(reportMd,report);const auto diagnostics=DiagnosticEngine::analyze(ScenarioEngine::toString(last.scenario),last.tick,last.sensors,last.issues,lab.recorder(),lab.eventLog());if(diagnosticSummary){std::cout<<" DIAGNOSTICS health="<<diagnostics.healthScore<<" findings="<<diagnostics.findings.size()<<" faults="<<diagnostics.faultCount<<" warnings="<<diagnostics.warningCount<<" fingerprint="<<diagnostics.fingerprint<<'\n';}if(!diagnosticJson.empty())DiagnosticReport::writeJson(diagnosticJson,diagnostics);if(!diagnosticMd.empty())DiagnosticReport::writeMarkdown(diagnosticMd,diagnostics);if(!diagnosticCasebook.empty()){DiagnosticCaseRecord record;record.id="DX-"+std::to_string(last.tick);record.title="Synthetic diagnostic case — "+scenarioName;record.openedTick=last.tick;record.updatedTick=last.tick;for(const auto& finding:diagnostics.findings)record.findingCodes.push_back(finding.code);record.notes.push_back("Generated by NEXVARY Avionics Lab training diagnostic engine");DiagnosticCasebook::writeFile(diagnosticCasebook,std::vector<DiagnosticCaseRecord>{record});}return 0;}catch(const std::exception& ex){std::cerr<<"error: "<<ex.what()<<'\n';return 1;}}
